// And groups predicates with the AND operator between them.
func And(predicates ...predicate.TeacherAbsence) predicate.TeacherAbsence {
	return predicate.TeacherAbsence(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.TeacherAbsence) predicate.TeacherAbsence {
	return predicate.TeacherAbsence(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.TeacherAbsence) predicate.TeacherAbsence {
	return predicate.TeacherAbsence(sql.NotPredicates(p))
}
